describe('listing conversations over the socket', () => {
  it('answers list_sessions for the session user with ISO dates, or empty when listFor is absent', async () => {
    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
    const createdAt = new Date('2026-03-10T10:00:00.000Z');
    const updatedAt = new Date('2026-03-10T10:05:00.000Z');
    const store = {
      listFor: async (userId: string | number, options?: SessionListOptions) => {
        seen.push({userId, options});
        return [{sessionId: 'chat-1', createdAt, updatedAt, entryCount: 2}];
      },
    } as unknown as SessionStore;

    const sent: OutgoingMessage[] = [];
    const ws = {send: (raw: string) => void sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
    const orchestrator = {} as ChatOrchestrator;
    const before: SessionCursor = {updatedAt: '2026-03-10T10:10:00.000Z', sessionId: 'chat-2'};
    await createMessageHandler(orchestrator, store)(ws, session, {
      type: 'list_sessions',
      limit: 5,
      before,
      userId: 'u2',
    });
    await createMessageHandler(orchestrator)(ws, session, {type: 'list_sessions'});

    expect({seen, sent}).toEqual({
      seen: [{userId: 'u1', options: {limit: 5, before}}],
      sent: [
        {
          type: 'session_list',
          sessions: [
            {
              sessionId: 'chat-1',
              createdAt: createdAt.toISOString(),
              updatedAt: updatedAt.toISOString(),
              entryCount: 2,
            },
          ],
        },
        {type: 'session_list', sessions: []},
      ],
    });
  });

  it('logs under ws with userId and sends SERVER_ERROR when listFor throws', async () => {
    const errors: Array<{category: string; message: string; fields?: Record<string, unknown>}> = [];
    setLogger({
      debug: () => undefined,
      info: () => undefined,
      warn: () => undefined,
      error: (category, message, fields) => void errors.push({category, message, fields}),
    });
    const sent: OutgoingMessage[] = [];
    try {
      const ws = {send: (raw: string) => void sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
      const store = {
        listFor: async () => {
          throw new Error('database offline');
        },
      } as unknown as SessionStore;
      const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
      await createMessageHandler({} as ChatOrchestrator, store)(ws, session, {type: 'list_sessions'});
    } finally {
      setLogger();
    }

    expect({
      sent: sent.map(frame => (frame.type === 'error' ? {type: frame.type, code: frame.code} : frame)),
      errors,
    }).toEqual({
      sent: [{type: 'error', code: 'SERVER_ERROR'}],
      errors: [
        {
          category: 'ws',
          message: expect.any(String),
          fields: expect.objectContaining({userId: 'u1', error: 'database offline'}),
        },
      ],
    });
  });
});

